<?php
$availableSemesters=safeRun($pdo,"SELECT DISTINCT se.* FROM semesters se JOIN lecturer_roles lr ON lr.semester_id=se.id WHERE lr.lecturer_id=? AND lr.role_type='coordinator' ORDER BY se.start_date DESC",[$lecturerId])->fetchAll();
$selectedSemesterId=(int)($_GET['semester_id']??$currentSemesterId);$allowedProgrammes=roleProgrammesForLecturer($pdo,$lecturerId,'coordinator',$selectedSemesterId);if(!$allowedProgrammes&&$availableSemesters){$selectedSemesterId=(int)$availableSemesters[0]['id'];$allowedProgrammes=roleProgrammesForLecturer($pdo,$lecturerId,'coordinator',$selectedSemesterId);}$rows=$allowedProgrammes?semesterProgrammeResults($pdo,$selectedSemesterId,$allowedProgrammes):[];
?>
