<div class="card-fy mb-3"><div class="d-flex justify-content-between align-items-end gap-3 flex-wrap"><div><div class="section-title mb-1">Student Marks and Grades</div><p class="small text-muted mb-0">Select each student's next outcome manually. No student is promoted automatically.</p></div><form method="get"><input type="hidden" name="view" value="student-results"><label class="form-label small fw-semibold">Semester</label><select name="semester_id" class="form-control-fy" onchange="this.form.submit()"><?php foreach($availableSemesters as $semester): ?><option value="<?= (int)$semester['id'] ?>" <?= (int)$semester['id']===$selectedSemesterId?'selected':'' ?>><?= e($semester['name']) ?></option><?php endforeach; ?></select></form></div></div>
<div class="card-fy"><div class="table-responsive"><table class="table-fy"><thead><tr><th>Student</th><th>Stage</th><th>Project</th><th>Total</th><th>Grade</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $row):$isFyp1=str_ends_with($row['programme_type'],'fyp1');$canDecide=$selectedSemesterId===$currentSemesterId&&($row['result_status']??'')==='released'; ?><tr><td><strong><?= e($row['full_name']) ?></strong><div class="small text-muted"><?= e($row['matric_number']) ?></div></td><td><?= e(programmeTypeLabel($row['programme_type'])) ?></td><td class="small"><?= e($row['project_title']?:'No project title') ?></td><td><?= $row['final_score']!==null?e(number_format((float)$row['final_score'],2)).'%':'—' ?></td><td><strong><?= e($row['grade']??'—') ?></strong></td><td><div class="small text-muted mb-2">Current: <?= e(ucfirst($row['status'])) ?></div><?php if(!$canDecide): ?><span class="small text-muted"><?= $selectedSemesterId!==$currentSemesterId?'Historical record — no progression action.':'Release the final result before selecting progression.' ?></span><?php else: ?><div class="d-flex gap-2 flex-wrap"><?php if($isFyp1): ?><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="set_student_progression"><input type="hidden" name="student_id" value="<?= (int)$row['student_id'] ?>"><input type="hidden" name="semester_id" value="<?= $selectedSemesterId ?>"><input type="hidden" name="decision" value="retake_fyp1"><button class="btn btn-outline-danger btn-sm">Retake FYP1</button></form><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="set_student_progression"><input type="hidden" name="student_id" value="<?= (int)$row['student_id'] ?>"><input type="hidden" name="semester_id" value="<?= $selectedSemesterId ?>"><input type="hidden" name="decision" value="promote_fyp2"><button class="btn-fy-orange btn-sm">Promote FYP2</button></form><?php else: ?><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="set_student_progression"><input type="hidden" name="student_id" value="<?= (int)$row['student_id'] ?>"><input type="hidden" name="semester_id" value="<?= $selectedSemesterId ?>"><input type="hidden" name="decision" value="retake_fyp2"><button class="btn btn-outline-danger btn-sm">Retake FYP2</button></form><form method="post" onsubmit="return confirm('Mark this student as completed and deactivate the active FYP enrolment?')"><?= csrfField() ?><input type="hidden" name="action" value="set_student_progression"><input type="hidden" name="student_id" value="<?= (int)$row['student_id'] ?>"><input type="hidden" name="semester_id" value="<?= $selectedSemesterId ?>"><input type="hidden" name="decision" value="completed_fyp"><button class="btn-fy-orange btn-sm">Completed FYP</button></form><?php endif; ?></div><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="text-center text-muted py-5">No student records are available.</td></tr><?php endif; ?></tbody></table></div></div>
